#include <stdio.h>
/*
 * ex04：归结反驳（resolution refutation）
 * 为什么：这是「机器如何证明定理」的最简实现 —— 把前提与结论的否定都化成子句，
 *        两两消去互补文字，若能推出空子句 □，则原子句集不可满足，命题得证。
 * 本例证明 (p∨q) ∧ (¬p∨r) ∧ (¬q∨r) ∧ ¬r 不可满足。
 * 子句用位掩码表示：bit 2i = 文字 xi，bit 2i+1 = 文字 ¬xi。
 */
#define NV 3
static int comp(int lit) { return lit ^ 1; }        /* 取反文字 */
static int resolve(int a, int b, int *out) {
    int res = 0, eliminated = 0;
    for (int l = 0; l < 2 * NV; l++) {
        int ina = (a >> l) & 1, inb = (b >> l) & 1;
        /* 两个方向都要跳过：a 的 l 与 b 的 ~l 互补；b 的 l 与 a 的 ~l 互补 */
        if (ina && ((b >> comp(l)) & 1)) { eliminated = 1; continue; }
        if (inb && ((a >> comp(l)) & 1)) { eliminated = 1; continue; }
        if (ina || inb) {
            if ((res >> comp(l)) & 1) return -1;     /* 出现互补文字 -> 重言式，无用 */
            res |= (1 << l);
        }
    }
    if (!eliminated) return -1;                        /* 没有可消文字，不产生归结式 */
    *out = res;
    return 0;
}
static void show(int c) {
    if (!c) { printf("[]"); return; }
    printf("[");
    int first = 1;
    for (int l = 0; l < 2 * NV; l++)
        if ((c >> l) & 1) {
            if (!first) printf(", ");
            printf("%s%d", (l & 1) ? "~" : "", l / 2 + 1);
            first = 0;
        }
    printf("]");
}
int main(void) {
    int cls[16] = {
        (1 << 0) | (1 << 2),   /* p v q   */
        (1 << 1) | (1 << 4),   /* ~p v r  */
        (1 << 3) | (1 << 4),   /* ~q v r  */
        (1 << 5)                /* ~r      */
    };
    int n = 4, step = 0, proved = 0;
    printf("start clauses:\n");
    for (int i = 0; i < n; i++) { printf("  C%d = ", i + 1); show(cls[i]); printf("\n"); }

    while (!proved) {
        int added = 0;
        for (int i = 0; i < n && !proved; i++)
            for (int j = i + 1; j < n && !proved; j++) {
                int r;
                if (resolve(cls[i], cls[j], &r) != 0) continue;
                int dup = 0;
                for (int k = 0; k < n; k++) if (cls[k] == r) dup = 1;
                if (dup) continue;
                step++;
                printf("\nstep %d: ", step);
                show(cls[i]); printf(" + "); show(cls[j]);
                printf("  ==>  "); show(r); printf("\n");
                cls[n++] = r;
                added = 1;
                if (r == 0) { proved = 1; }
                if (n >= 16) break;
            }
        if (!added) break;
    }
    printf("\n%s\n", proved ? "derived the empty clause [] -> UNSATISFIABLE, so the original formula is proved."
                            : "no empty clause derived -> satisfiable (or need more steps).");
    printf("resolution steps used: %d, clauses in memory: %d\n", step, n);
    return 0;
}
